    <style>
        /* Styles temporaires pour les nouveaux éléments - à intégrer dans blog.css après test */
        /* Fil d'Ariane */
        .breadcrumb-nav {
            background-color: #f8f9fa;
            padding: 15px 0;
            border-bottom: 1px solid #e9ecef;
        }
        
        .breadcrumb {
            display: flex;
            list-style: none;
            padding: 0;
            margin: 0;
            flex-wrap: wrap;
        }
        
        .breadcrumb-item {
            display: flex;
            align-items: center;
        }
        
        .breadcrumb-item + .breadcrumb-item::before {
            content: "/";
            padding: 0 10px;
            color: #6c757d;
        }
        
        .breadcrumb-item a {
            color: #2c5aa0;
            text-decoration: none;
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 0.9rem;
            transition: all 0.3s ease;
        }
        
        .breadcrumb-item a:hover {
            color: #ff6b35;
            text-decoration: underline;
        }
        
        .breadcrumb-item.active {
            color: #6c757d;
            font-size: 0.9rem;
        }
        
        /* Gestion utilisateurs dans header */
        .user-actions {
            margin-left: 20px;
        }
        
        .guest-actions {
            display: flex;
            gap: 10px;
            align-items: center;
        }
        
        .login-btn {
            color: #333;
            font-weight: 600;
            padding: 8px 16px;
            border-radius: 4px;
            transition: all 0.3s ease;
            text-decoration: none;
        }
        
        .login-btn:hover {
            color: #2c5aa0;
            background-color: #e9ecef;
        }
        
        .register-btn {
            background-color: #4ecdc4;
            color: white;
            padding: 8px 16px;
            border-radius: 4px;
            text-decoration: none;
            font-weight: 600;
        }
        
        .register-btn:hover {
            background-color: #2c5aa0;
            color: white;
        }
        
        /* ===== RÉFÉRENCEMENT IMPLICITE ===== */
        
        /* Suggestions contextuelles */
        .contextual-links {
            margin: 40px 0;
            padding: 30px;
            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
            border-radius: 12px;
            border-left: 5px solid #2c5aa0;
        }
        
        .contextual-links-header {
            display: flex;
            align-items: center;
            gap: 15px;
            margin-bottom: 25px;
        }
        
        .contextual-links-header i {
            font-size: 1.8rem;
            color: #2c5aa0;
            background: white;
            width: 50px;
            height: 50px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
        }
        
        .contextual-links-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 20px;
        }
        
        .contextual-link-card {
            background: white;
            border-radius: 10px;
            padding: 25px;
            text-align: center;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            transition: all 0.3s ease;
            border: 1px solid transparent;
        }
        
        .contextual-link-card:hover {
            transform: translateY(-8px);
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
            border-color: #2c5aa0;
        }
        
        .contextual-link-icon {
            width: 70px;
            height: 70px;
            margin: 0 auto 20px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.8rem;
            color: white;
        }
        
        .icon-sante { background: #ff6b35; }
        .icon-tourisme { background: #4ecdc4; }
        .icon-business { background: #2c5aa0; }
        .icon-devweb { background: #9c27b0; }
        
        .contextual-link-card h4 {
            margin-bottom: 10px;
            color: #333;
        }
        
        .contextual-link-card p {
            color: #6c757d;
            font-size: 0.9rem;
            margin-bottom: 20px;
            line-height: 1.5;
        }
        
        /* Bloc après article */
        .article-suggestions {
            margin-top: 50px;
            padding-top: 30px;
            border-top: 2px solid #e9ecef;
        }
        
        .suggestions-header {
            text-align: center;
            margin-bottom: 40px;
        }
        
        .suggestions-header h3 {
            color: #2c5aa0;
            margin-bottom: 15px;
        }
        
        .suggestions-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }
        
        .suggestion-card {
            background: white;
            border-radius: 10px;
            overflow: hidden;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            transition: all 0.3s ease;
            border: 1px solid #e9ecef;
        }
        
        .suggestion-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 30px rgba(0, 0, 0, 0.1);
        }
        
        .suggestion-image {
            height: 180px;
            background-size: cover;
            background-position: center;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 2.5rem;
        }
        
        .suggestion-content {
            padding: 25px;
        }
        
        .suggestion-content h4 {
            margin-bottom: 15px;
            color: #2c5aa0;
        }
        
        .suggestion-content p {
            color: #6c757d;
            margin-bottom: 20px;
            line-height: 1.6;
        }
        
        /* Badges formations */
        .formation-badge {
            display: inline-block;
            padding: 5px 12px;
            border-radius: 20px;
            font-size: 0.8rem;
            font-weight: 600;
            margin-right: 8px;
            margin-bottom: 10px;
        }
        
        .badge-sante { background: #ff6b35; color: white; }
        .badge-tourisme { background: #4ecdc4; color: white; }
        .badge-business { background: #2c5aa0; color: white; }
        .badge-devweb { background: #9c27b0; color: white; }
        
        /* CTA footer d'article */
        .article-cta {
            background: linear-gradient(135deg, #2c5aa0 0%, #1a3a6e 100%);
            color: white;
            padding: 40px;
            border-radius: 12px;
            text-align: center;
            margin: 60px 0 30px;
        }
        
        .article-cta h3 {
