    <script>
        // Ajouter le gestionnaire de référencement implicite au chargement
        document.addEventListener('DOMContentLoaded', function() {
            // Créer la classe ContextualReferenceManager
            class ContextualReferenceManager {
                constructor() {
                    this.contextualData = this.getContextualData();
                }
                
                getContextualData() {
                    return {
                        formations: [
                            {
                                id: 'sante',
                                title: 'Formations Santé',
                                icon: 'fas fa-heartbeat',
                                color: '#ff6b35',
                                description: 'Infirmier, Kinésithérapeute, Aide-soignant',
                                link: '<?php echo esc_url(groupe1_convergence_section_url('formations', 'sante')); ?>',
                                tags: ['medical', 'soin', 'clinique']
                            },
                            {
                                id: 'tourisme',
                                title: 'Formations Tourisme',
                                icon: 'fas fa-plane',
                                color: '#4ecdc4',
                                description: 'Management hôtelier, Guide touristique',
                                link: '<?php echo esc_url(groupe1_convergence_section_url('formations', 'tourisme')); ?>',
                                tags: ['voyage', 'hotellerie', 'guide']
                            },
                            {
                                id: 'business',
                                title: 'Formations Business',
                                icon: 'fas fa-chart-line',
                                color: '#2c5aa0',
                                description: 'MBA, Marketing Digital, Management',
                                link: '<?php echo esc_url(groupe1_convergence_section_url('formations', 'business')); ?>',
                                tags: ['management', 'marketing', 'commerce']
                            },
                            {
                                id: 'devweb',
                                title: 'Formations Dev Web',
                                icon: 'fas fa-laptop-code',
                                color: '#9c27b0',
                                description: 'Développeur Full-Stack, Front-End',
                                link: '<?php echo esc_url(groupe1_convergence_section_url('formations', 'devweb')); ?>',
                                tags: ['programmation', 'web', 'code']
                            }
                        ],
                        autresPages: [
                            {
                                title: 'FAQ Étudiants',
                                description: 'Trouvez réponses à vos questions fréquentes',
                                icon: 'fas fa-question-circle',
                                link: '<?php echo esc_url(home_url('/faq/')); ?>',
                                imageColor: '#2c5aa0'
                            },
                            {
                                title: 'Contactez-nous',
                                description: 'Échangez avec notre équipe pédagogique',
                                icon: 'fas fa-envelope',
                                link: '<?php echo esc_url(home_url('/contact/')); ?>',
                                imageColor: '#4ecdc4'
                            },
                            {
                                title: 'Témoignages',
                                description: 'Découvrez les parcours de nos diplômés',
                                icon: 'fas fa-comments',
                                link: '<?php echo esc_url(groupe1_convergence_section_url('home', 'testimonials')); ?>',
                                imageColor: '#ff6b35'
                            }
                        ]
                    };
                }
                
                // Générer les liens contextuels selon le contenu de l'article
                generateContextualLinks(articleContent) {
                    const keywords = this.extractKeywords(articleContent);
                    const relevantFormations = this.getRelevantFormations(keywords);
                    
                    return `
                        <div class="contextual-links">
                            <div class="contextual-links-header">
                                <i class="fas fa-link"></i>
                                <div>
                                    <h3>Formations liées à cet article</h3>
                                    <p>Découvrez les formations Convergence correspondant à vos intérêts</p>
                                </div>
                            </div>
                            
                            <div class="contextual-links-grid">
                                ${relevantFormations.map(formation => `
                                    <div class="contextual-link-card">
                                        <div class="contextual-link-icon ${'icon-' + formation.id}">
                                            <i class="${formation.icon}"></i>
                                        </div>
                                        <h4>${formation.title}</h4>
                                        <p>${formation.description}</p>
                                        <a href="${formation.link}" class="btn btn-small" style="background-color: ${formation.color}; color: white;">
                                            Découvrir
                                        </a>
                                    </div>
                                `).join('')}
                            </div>
                        </div>
                    `;
                }
                
                // Extraire les mots-clés du contenu
                extractKeywords(content) {
                    const commonWords = ['le', 'la', 'les', 'de', 'des', 'du', 'et', 'ou', 'à', 'au', 'aux', 'dans', 'par', 'pour', 'sur'];
                    const words = content.toLowerCase()
                        .replace(/[^\w\s]/g, ' ')
                        .split(/\s+/)
                        .filter(word => word.length > 3 && !commonWords.includes(word));
                    
                    // Compter les occurrences
                    const wordCount = {};
                    words.forEach(word => {
                        wordCount[word] = (wordCount[word] || 0) + 1;
                    });
                    
                    // Retourner les 10 mots les plus fréquents
                    return Object.entries(wordCount)
                        .sort((a, b) => b[1] - a[1])
                        .slice(0, 10)
                        .map(entry => entry[0]);
                }
                
                // Obtenir les formations pertinentes selon les mots-clés
                getRelevantFormations(keywords) {
                    const formations = this.contextualData.formations;
                    const scoredFormations = formations.map(formation => {
                        let score = 0;
                        formation.tags.forEach(tag => {
                            if (keywords.some(keyword => keyword.includes(tag) || tag.includes(keyword))) {
                                score++;
                            }
                        });
                        return { ...formation, score };
                    });
                    
                    // Trier par score et prendre les 2 meilleures
                    return scoredFormations
                        .filter(f => f.score > 0)
                        .sort((a, b) => b.score - a.score)
                        .slice(0, 2);
                }
                
                // Générer les suggestions après article
                generateArticleSuggestions(articleId) {
                    const suggestions = this.contextualData.autresPages;
                    
                    return `
                        <div class="article-suggestions">
                            <div class="suggestions-header">
                                <h3>Pour aller plus loin</h3>
                                <p>Découvrez nos autres ressources pour compléter votre lecture</p>
                            </div>
                            
                            <div class="suggestions-grid">
                                ${suggestions.map(suggestion => `
                                    <div class="suggestion-card">
                                        <div class="suggestion-image" style="background: linear-gradient(135deg, ${suggestion.imageColor}, ${this.lightenColor(suggestion.imageColor, 20)});">
                                            <i class="${suggestion.icon}"></i>
                                        </div>
                                        <div class="suggestion-content">
                                            <h4>${suggestion.title}</h4>
                                            <p>${suggestion.description}</p>
                                            <a href="${suggestion.link}" class="btn btn-small">
                                                <i class="fas fa-arrow-right"></i> Explorer
                                            </a>
                                        </div>
                                    </div>
                                `).join('')}
                            </div>
                        </div>
                    `;
                }
                
                // Générer le CTA après article
                generateArticleCTA(articleCategory) {
                    return `
                        <div class="article-cta">
                            <h3>Cet article vous a plu ?</h3>
                            <p>Découvrez nos formations dans ce domaine et construisez votre avenir professionnel avec Convergence.</p>
                            <div class="cta-buttons">
                                <a href="<?php echo esc_url(home_url('/formations/')); ?>" class="cta-btn">
                                    <i class="fas fa-graduation-cap"></i> Voir nos formations
                                </a>
                                <a href="<?php echo esc_url(home_url('/contact/')); ?>" class="cta-btn cta-btn-secondary">
                                    <i class="fas fa-comments"></i> Discuter avec un conseiller
                                </a>
                            </div>
                        </div>
                    `;
                }
                
                // Générer le bloc ressources
                generateResourcesBlock(articleId) {
                    return `
                        <div class="resources-block">
                            <h4><i class="fas fa-book-open"></i> Ressources complémentaires</h4>
                            <ul class="resources-list">
                                <li>
                                    <i class="fas fa-file-pdf"></i>
                                    <a href="<?php echo esc_url(add_query_arg('subject', 'brochure', home_url('/contact/'))); ?>" onclick="downloadBrochure()">Télécharger notre brochure formations (PDF)</a>
                                </li>
                                <li>
                                    <i class="fas fa-calendar-alt"></i>
                                    <a href="<?php echo esc_url(add_query_arg('subject', 'webinar', home_url('/contact/'))); ?>" onclick="showWebinarModal()">S'inscrire à notre prochain webinar découverte</a>
                                </li>
                                <li>
                                    <i class="fas fa-chalkboard-teacher"></i>
                                    <a href="<?php echo esc_url(home_url('/faq/')); ?>">Consulter la FAQ étudiante</a>
                                </li>
                                <li>
                                    <i class="fas fa-handshake"></i>
                                    <a href="<?php echo esc_url(home_url('/contact/')); ?>">Prendre rendez-vous avec un conseiller</a>
                                </li>
                            </ul>
                        </div>
                    `;
                }
                
                // Éclaircir une couleur
                lightenColor(color, percent) {
                    const num = parseInt(color.replace("#", ""), 16);
                    const amt = Math.round(2.55 * percent);
                    const R = (num >> 16) + amt;
                    const G = (num >> 8 & 0x00FF) + amt;
                    const B = (num & 0x0000FF) + amt;
                    return "#" + (
                        0x1000000 +
                        (R < 255 ? R < 1 ? 0 : R : 255) * 0x10000 +
                        (G < 255 ? G < 1 ? 0 : G : 255) * 0x100 +
                        (B < 255 ? B < 1 ? 0 : B : 255)
                    ).toString(16).slice(1);
                }
            }
            
            // Ajouter au scope global
            window.ContextualReferenceManager = ContextualReferenceManager;
            
            // Fonction pour simuler le téléchargement de brochure
            window.downloadBrochure = function() {
                alert('Merci pour votre intérêt ! Le téléchargement de la brochure débutera bientôt.');
                // Ici, ajouter la logique de téléchargement réel
            };
            
            // Fonction pour montrer le modal webinar
            window.showWebinarModal = function() {
                alert('Inscription au webinar disponible prochainement. Consultez notre page Formations pour plus d\'informations.');
                // Ici, ajouter la logique du modal webinar
            };
        });
